) -> bool
    recommends
        0 <= bound <= queued_ops.len(),
{
    forall|j|
        0 <= j < bound ==> localUpdates.contains_key(#[trigger] queued_ops[j]) ==> {
            ||| localUpdates[queued_ops[j]].is_Applied()
            ||| localUpdates[queued_ops[j]].is_Done()
        }
}

